// Whatever the form actually names the uploaded binary field,
// normalize it to a fixed key ('data') so downstream nodes never
// depend on guessing the form's binary property name.
// Also strips a leading UTF-8 BOM (EF BB BF), which otherwise breaks
// the CSV parser's opening-quote detection on field 0, line 1.
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) {
    throw new Error('No file found on the incoming item — check the form upload.');
  }
  const firstKey = binaryKeys[0];
  const originalMeta = item.binary[firstKey];

  const buffer = await this.helpers.getBinaryDataBuffer(i, firstKey);
  const hasBom = buffer.length >= 3 && buffer[0] === 0xEF && buffer[1] === 0xBB && buffer[2] === 0xBF;
  const cleanBuffer = hasBom ? buffer.slice(3) : buffer;

  const newBinary = await this.helpers.prepareBinaryData(
    cleanBuffer,
    originalMeta.fileName || 'upload.csv',
    originalMeta.mimeType || 'text/csv'
  );

  results.push({
    json: item.json,
    binary: {
      data: newBinary
    }
  });
}

return results;

// One item per CSV row -> build the full document text (pageContent)
// AND duplicate the key fields into metadata, so Test Case ID / Summary
// survive even if the text splitter cuts a long row into multiple chunks.
const items = $input.all();

return items.map(item => {
  const d = item.json;
  const testCaseId = (d['Test Case ID'] || '').toString().trim();
  const summary = (d['Summary'] || '').toString().trim();

  const pageContent = [
    `Test Case ID: ${testCaseId}`,
    `Summary: ${summary}`,
    `Category: ${d['Category'] || ''}`,
    `Scenario Type: ${d['Scenario Type'] || ''}`,
    `Test Type: ${d['Test Type'] || ''}`,
    `Priority: ${d['Priority'] || ''}`,
    `Preconditions: ${d['Preconditions'] || ''}`,
    `Test Data: ${d['Test Data'] || ''}`,
    `Test Steps: ${d['Test Steps'] || ''}`,
    `Expected Result: ${d['Expected Result'] || ''}`,
    `Actual Result: ${d['Actual Result'] || ''}`,
    `Execution Status: ${d['Execution Status'] || ''}`,
    `Environment: ${d['Environment'] || ''}`,
    `Assumptions / Applicability: ${d['Assumptions / Applicability'] || ''}`
  ].join('\n');

  return {
    json: {
      pageContent,
      metadata: {
        testCaseId,
        summary,
        category: d['Category'] || '',
        priority: d['Priority'] || '',
        testType: d['Test Type'] || '',
        executionStatus: d['Execution Status'] || '',
        environment: d['Environment'] || '',
        source: d['Jira Import Notes'] || ''
      }
    }
  };
});
